from collections import Counter
def transform2(g):
    h,w=len(g),len(g[0])
    # components
    seen=[[False]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                c=g[i][j]; stack=[(i,j)]; cells=[]; seen[i][j]=True
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; stack.append((ny,nx))
                comps.append((c,cells))
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    noise={(i,j) for c,cells in comps if len(cells)==1 for (i,j) in cells}
    def comp_at(y,x):
        for c,cells in comps:
            if (y,x) in cells: return c,cells
    out=[r[:] for r in g]
    for (y,x) in noise:
        cand=[]
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and (ny,nx) not in noise:
                c,cells=comp_at(ny,nx)
                ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                add={(y,x)}|{(i,j) for (i,j) in noise if y0<=i<=y1 and x0<=j<=x1}
                area=(y1-y0+1)*(x1-x0+1)
                if len(cells)+len(add)==area:
                    cand.append(c)
        if len(set(cand))==1:
            out[y][x]=cand[0]
        else:
            nb=[g[y+dy][x+dx] for dy,dx in((1,0),(-1,0),(0,1),(0,-1)) if 0<=y+dy<h and 0<=x+dx<w and (y+dy,x+dx) not in noise]
            if nb:
                mc=Counter(nb).most_common()
                out[y][x]= mc[0][0] if len(mc)==1 or mc[0][1]>mc[1][1] else bg
            else:
                out[y][x]=bg
    return out
